  async Task<bool> Perform(string title,Action<CancellationToken> action){if(busy)return false;rarRebuildApproved=false;using(var token=new CancellationTokenSource()){active=token;operationTitle=title;SetBusy(true,title);var watch=Stopwatch.StartNew();bool show=title.StartsWith("Extracting")||title.StartsWith("Testing")||title.StartsWith("Creating")||title.StartsWith("Adding")||title.StartsWith("Updating");try{while(true){try{if(show){progressWindow=new ProgressWindow(Window,title,operationSource??(archive!=null?archive.File:""),operationBytes,()=>token.Cancel());progressWindow.Window.Show();Window.TaskbarItemInfo=new System.Windows.Shell.TaskbarItemInfo{ProgressState=System.Windows.Shell.TaskbarItemProgressState.Indeterminate};}await Task.Run(()=>action(token.Token));CloseProgress();Status("Completed in "+watch.Elapsed.TotalSeconds.ToString("0.00")+" s");return true;}catch(EngineException ex){CloseProgress();if(!ex.PasswordRequired)throw;SetBusy(false,"Password needed");string p=PasswordDialog();if(p==null)return false;password=p;SetBusy(true,title);}catch(RarRebuildRequiredException){CloseProgress();SetBusy(false,"RAR rebuild needs confirmation");if(!Confirm("Rebuild this RAR?","This archive has extra features BeniZip cannot preserve. Rebuilding keeps the files but may remove recovery data, quick-open information or other archive settings. A backup of the original will be saved beside it.","Rebuild & edit"))return false;rarRebuildApproved=true;SetBusy(true,title);}}}catch(OperationCanceledException){CloseProgress();Status("Cancelled · existing files were kept");return false;}catch(Exception ex){CloseProgress();Status("Operation stopped");Notify("The operation could not finish",ex.Message);return false;}finally{CloseProgress();string result=Find<TextBlock>("StatusText").Text;SetBusy(false,result);active=null;operationBytes=0;operationSource=null;}}}
  async void Navigate(string path){await NavigateAsync(path);}
  async Task NavigateAsync(string path){if(busy)return;path=(path??"").Trim().Trim('"');if(path.Length==0)return;if(!File.Exists(path)&&!Directory.Exists(path)){Notify("Path not found","Choose an existing archive or folder.\n\n"+path);return;}
   if(Directory.Exists(path)){string target=Path.GetFullPath(path);var result=new List<FileRow>();bool ok=await Perform("Opening folder",t=>{var info=new DirectoryInfo(target);if(info.Parent!=null)result.Add(new FileRow{Name="..",Path=info.Parent.FullName,Folder=true,Parent=true,Type="Parent folder"});foreach(var d in info.EnumerateDirectories()){t.ThrowIfCancellationRequested();result.Add(new FileRow{Name=d.Name,Path=d.FullName,Folder=true,Type="Folder",Modified=d.LastWriteTime.ToString("dd MMM yyyy")});}foreach(var f in info.EnumerateFiles()){t.ThrowIfCancellationRequested();if((f.Attributes&FileAttributes.Hidden)!=0)continue;result.Add(new FileRow{Name=f.Name,Path=f.FullName,Size=f.Length,Packed=f.Length,Type=ArchiveEngine.IsArchive(f.Name)?"Archive":f.Extension.TrimStart('.').ToUpperInvariant()+" file",Modified=f.LastWriteTime.ToString("dd MMM yyyy")});}});if(ok){archive=null;folder=target;inner="";password=null;rows=result;Address.Text=target;Text("PageTitle",new DirectoryInfo(target).Name);Text("TitleFile","File explorer");Text("PageSubtitle","Folders and archives");Search.Clear();Filter();Status(result.Count(x=>!x.Parent)+" items · drop an archive to open it");}return;}
   if(!ArchiveEngine.IsArchive(path)){Notify("Choose an archive","This file type is opened through its own application. You can select it and choose Create to compress it.");return;}
   ArchiveIndex index=null;string file=Path.GetFullPath(path);var timer=Stopwatch.StartNew();if(await Perform("Reading archive index",t=>index=ArchiveEngine.List(file,password,t))){archive=index;folder=Path.GetDirectoryName(file);inner="";Remember(file);Search.Clear();ShowArchive();Status(index.Items.Count+" entries · index ready in "+timer.Elapsed.TotalMilliseconds.ToString("0")+" ms");if(StartupAction!=null){string action=StartupAction;StartupAction=null;if(action=="extract-here")ExtractHere();else ExtractDialog(false);}}
  }
  void ShowArchive(){if(archive==null)return;rows=new List<FileRow>{new FileRow{Name="..",Folder=true,Parent=true,Type="Parent folder",Path=""}};var dirs=new HashSet<string>(StringComparer.Ordinal);
   foreach(var entry in archive.Items){if(!entry.Path.StartsWith(inner,StringComparison.Ordinal))continue;string rest=entry.Path.Substring(inner.Length).TrimEnd('/');if(rest.Length==0)continue;int slash=rest.IndexOf('/');if(slash>=0||entry.Folder){string name=slash>=0?rest.Substring(0,slash):rest;if(dirs.Add(name))rows.Add(new FileRow{Name=name,Path=inner+name,Folder=true,Type="Folder"});}else rows.Add(new FileRow{Name=rest,Path=entry.Path,Size=entry.Size,Packed=entry.Packed,Modified=FormatDate(entry.Modified),Type=Path.GetExtension(rest).TrimStart('.').ToUpperInvariant()+" file",Crc=entry.Crc});}
   Address.Text=archive.File+(inner.Length>0?"  ›  "+inner:"");Text("PageTitle",Path.GetFileName(archive.File));Text("TitleFile",Path.GetFileName(archive.File));Text("PageSubtitle",nested?"Nested archive · extract it to edit its contents":archive.Format+" archive  ·  "+archive.Items.Count(x=>!x.Folder)+" files  ·  "+ArchiveEngine.FormatSize(archive.Total)+" unpacked");Filter();
  }
  static string FormatDate(string value){DateTime date;return DateTime.TryParse(value,out date)?date.ToString("dd MMM yyyy"):value;}
  void Filter(){string query=Search.Text.Trim();IEnumerable<FileRow> source=rows.Where(r=>r.Parent||query.Length==0||r.Name.IndexOf(query,StringComparison.CurrentCultureIgnoreCase)>=0);Func<FileRow,IComparable> key=r=>sort=="SIZE"?(IComparable)r.Size:sort=="PACKED"?(IComparable)r.Packed:sort=="TYPE"?(IComparable)r.Type:sort=="MODIFIED"?(IComparable)r.Modified:(IComparable)r.Name;source=reverse?source.OrderBy(r=>r.Parent?0:r.Folder?1:2).ThenByDescending(key):source.OrderBy(r=>r.Parent?0:r.Folder?1:2).ThenBy(key);var visible=source.ToList();Files.ItemsSource=visible;Find<StackPanel>("EmptyPanel").Visibility=visible.Any(r=>!r.Parent)?Visibility.Collapsed:Visibility.Visible;Text("EmptyTitle",query.Length>0?"No matching files":"No files here");Inspector();}
  FileRow[] Selection(){return Files.SelectedItems.Cast<FileRow>().Where(x=>!x.Parent).ToArray();}
  void DragSelection(FileRow[] selected){
   if(archive==null){var paths=selected.Select(x=>x.Path).Where(x=>File.Exists(x)||Directory.Exists(x)).ToArray();if(paths.Length>0)System.Windows.DragDrop.DoDragDrop(Files,new DataObject(DataFormats.FileDrop,paths),DragDropEffects.Copy);return;}
