   try{
    using(var drag=new ArchiveDragDrop(current,prefix,members,()=>{
     operationBytes=current.Items.Where(x=>!x.Folder&&members.Any(p=>x.Path==p||x.Path.StartsWith(p.TrimEnd('/')+"/",StringComparison.Ordinal))).Sum(x=>x.Size);operationSource=current.File;
