  void Inspector(){var selected=Selection();Text("SelectionText",selected.Length>0?selected.Length+" selected · "+ArchiveEngine.FormatSize(selected.Sum(x=>x.Size)):rows.Count(r=>!r.Parent)+" items"+(archive!=null?" · "+ArchiveEngine.FormatSize(archive.Total)+" unpacked":""));bool opened=archive!=null,editable=opened&&!nested&&new[]{".zip",".7z",".rar"}.Contains(Path.GetExtension(archive.File).ToLowerInvariant());if(opened&&Path.GetExtension(archive.File).Equals(".rar",StringComparison.OrdinalIgnoreCase)&&!RarSupport.Available)editable=false;Enable("PreviewButton",!busy&&selected.Length==1);Enable("ExtractButton",!busy&&opened);Enable("TestButton",!busy&&opened);Enable("DeleteButton",!busy&&editable&&selected.Length>0);Enable("AddButton",!busy&&(!opened||editable));Enable("FindButton",!busy);Enable("InfoButton",!busy);foreach(string name in new[]{"MenuExtract","MenuExtractHere","MenuTest","MenuCloseArchive"}){var item=Find<MenuItem>(name);if(item!=null)item.IsEnabled=!busy&&opened;}foreach(string name in new[]{"MenuAddFolder","MenuDelete"}){var item=Find<MenuItem>(name);if(item!=null)item.IsEnabled=!busy&&editable&&(name!="MenuDelete"||selected.Length>0);}var view=Find<MenuItem>("MenuView");if(view!=null)view.IsEnabled=!busy&&selected.Length==1;}
  void Properties(){var selected=Selection();if(selected.Length==1){var r=selected[0];Notify("File information",r.Name+"\n\nType: "+r.Type+"\nPath: "+r.Path+"\nSize: "+r.Size.ToString("N0")+" bytes\nPacked: "+r.Packed.ToString("N0")+" bytes\nModified: "+r.Modified+(string.IsNullOrEmpty(r.Crc)?"":"\nCRC: "+r.Crc));}else if(archive!=null){Notify("Archive information",Path.GetFileName(archive.File)+"\n\nFormat: "+archive.Format+"\nFiles: "+archive.Items.Count(x=>!x.Folder).ToString("N0")+"\nArchive size: "+ArchiveEngine.FormatSize(archive.SourceLength)+"\nUnpacked size: "+ArchiveEngine.FormatSize(archive.Total)+"\n\n"+archive.File);}else Notify("Folder information",folder??"Choose a folder or archive.");}
  void RestoreWindowSize(){if(nested)return;try{string settings=Path.Combine(Updates.DataRoot,"window.json");if(!File.Exists(settings))return;var data=new JavaScriptSerializer().Deserialize<Dictionary<string,double>>(File.ReadAllText(settings));double width,height;if(data.TryGetValue("width",out width)&&data.TryGetValue("height",out height)){Window.Width=Math.Max(760,Math.Min(width,SystemParameters.WorkArea.Width*0.94));Window.Height=Math.Max(440,Math.Min(height,SystemParameters.WorkArea.Height*0.94));}}catch{}}
  void SaveWindowSize(){if(nested)return;try{var rect=Window.WindowState==WindowState.Normal?new Rect(Window.Left,Window.Top,Window.Width,Window.Height):Window.RestoreBounds;Directory.CreateDirectory(Updates.DataRoot);File.WriteAllText(Path.Combine(Updates.DataRoot,"window.json"),new JavaScriptSerializer().Serialize(new{width=rect.Width,height=rect.Height}));}catch{}}
  void OpenDialog(){if(busy)return;var dialog=new OpenFileDialog{Title="Open archive",Filter="Archives|*.zip;*.rar;*.7z;*.tar;*.gz;*.tgz;*.bz2;*.xz;*.zst;*.cab;*.iso;*.jar;*.arj;*.lzh;*.001;*.apk;*.epub;*.wim|All files|*.*",CheckFileExists=true};if(dialog.ShowDialog(Window)==true){password=null;Navigate(dialog.FileName);}}
  void Refresh(){if(!busy)Navigate(archive!=null?archive.File:folder??Downloads);}
  void GoUp(){if(busy)return;if(archive!=null){if(inner.Length==0){Navigate(folder);return;}string parent=inner.TrimEnd('/');int slash=parent.LastIndexOf('/');inner=slash<0?"":parent.Substring(0,slash+1);Search.Clear();ShowArchive();}else if(folder!=null&&Directory.GetParent(folder)!=null)Navigate(Directory.GetParent(folder).FullName);}
  async void ActivateSelected(){if(busy)return;var row=Files.SelectedItem as FileRow;if(row==null)return;if(row.Parent){GoUp();return;}if(archive==null){if(row.Folder||ArchiveEngine.IsArchive(row.Path)){password=null;Navigate(row.Path);}else Process.Start(new ProcessStartInfo(row.Path){UseShellExecute=true});return;}if(row.Folder){inner=row.Path.TrimEnd('/')+"/";Search.Clear();ShowArchive();return;}
   string extension=Path.GetExtension(row.Path).ToLowerInvariant();string[] texts={".txt",".md",".json",".xml",".csv",".log",".ini",".yaml",".yml",".cs",".cpp",".c",".h",".js",".ts",".html",".css",".srt",".nfo",".gitignore"};string[] images={".png",".jpg",".jpeg",".gif",".bmp",".ico"};bool nestedArchive=ArchiveEngine.IsArchive(row.Path),isText=texts.Contains(extension),isImage=images.Contains(extension);
   if(!nestedArchive&&!isText&&!isImage){Notify("Extract before opening","Extract this file to open it in its usual application.");ExtractDialog(true);return;}if(row.Size>128L*1024*1024&&!nestedArchive){Notify("This file is too large to preview","Extract it to open the full file.");return;}
   string temp=Path.Combine(Path.GetTempPath(),"BeniZip-Preview-"+Guid.NewGuid().ToString("N"));var current=archive;try{if(await Perform("Preparing preview",t=>ArchiveEngine.Extract(current,temp,new[]{row.Path},password,"Rename",t,Report))){string file=Path.Combine(temp,row.Path.Replace('/',Path.DirectorySeparatorChar));if(nestedArchive){var child=new ArchiveWindow(file,true);child.Window.Owner=Window;child.Window.ShowDialog();}else Preview(file,isText);}}finally{try{if(Directory.Exists(temp))Directory.Delete(temp,true);}catch{}}
  }
  async void ExtractDialog(bool selected){if(busy||archive==null)return;var selection=Selection();var options=ShowExtractDialog(archive,selected&&selection.Length>0,selection.Length);if(options==null)return;var current=archive;string[] members=options.Selected?selection.Select(x=>x.Path).ToArray():null;operationBytes=current.Items.Where(x=>!x.Folder&&(members==null||members.Any(p=>x.Path==p||x.Path.StartsWith(p.TrimEnd('/')+"/",StringComparison.Ordinal)))).Sum(x=>x.Size);operationSource=current.File;if(await Perform("Extracting files",t=>ArchiveEngine.Extract(current,options.Destination,members,password,options.Collision,t,Report))){Status("Extracted to "+options.Destination);if(options.OpenFolder)Process.Start("explorer.exe",ArchiveEngine.Quote(options.Destination));}}
