  async void CheckUpdates(bool manual){if(busy||dragActive||closed||nested)return;try{var update=await Updates.CheckAsync(manual);if(update==null){if(manual)Notify("BeniZip is up to date","The configured signed release channel has no newer version.");return;}if(!manual&&offered!=null&&offered>=update.Version)return;if(busy||dragActive||closed)return;offered=update.Version;if(!Confirm("BeniZip "+update.Version.ToString(3)+" is ready",update.Notes+"\n\nDownload size: "+ArchiveEngine.FormatSize(update.Size)+". BeniZip will verify the release, install it and restart.","Install & restart"))return;using(var token=new CancellationTokenSource()){active=token;SetBusy(true,"Downloading and verifying update");await Updates.DownloadAndInstall(update,token.Token);SetBusy(false,"Restarting BeniZip");Window.Close();}}catch(OperationCanceledException){SetBusy(false,"Update cancelled");}catch(Exception ex){SetBusy(false,"Update stopped");if(manual)Notify("The update could not be installed",ex.Message);}finally{active=null;}}
